import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import './Forum.css';
import ThreadList from '../Thread/ThreadList';
import LastThreadInfo from '../Thread/LastThreadInfo';

const ForumDetail = () => {
    const { id } = useParams();
    const [forum, setForum] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetch(`/data/forumDetail/forumDetail-${id}.json`)
            .then(response => response.json())
            .then(data => {
                setForum(data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Error fetching forum data:', error);
                setLoading(false);
            });
    }, [id]);

    if (loading) {
        return <p>Loading...</p>;
    }

    if (!forum) {
        return <p>Forum not found</p>;
    }

    const { subForums = [], breadcrumb = [], threads = [] } = forum;

    return (
        <div className="forum-detail">
            <nav className="breadcrumb">
                {breadcrumb.map((crumb, index) => (
                    <span key={index}>
                        <Link to={crumb.url}>{crumb.name}</Link>
                        {index < breadcrumb.length - 1 && " > "}
                    </span>
                ))}
            </nav>

            <div className="forum-item">
                <div className="forum-layout">
                    <div className="forum-status-image">
                        <img 
                            src={forum.hasNewPosts 
                                ? "https://i.servimg.com/u/f87/19/93/27/84/new10.png" 
                                : "https://i.servimg.com/u/f87/19/93/27/84/old_ca10.png"} 
                            alt={forum.hasNewPosts ? "New posts" : "No new posts"} 
                            className="status-image" 
                        />
                    </div>
                    <div className="forum-details">
                        <h3 className="forum-title">
                            {forum.forumName}
                        </h3>
                        <div className="forum-banner">
                            <img src={forum.bannerImage} alt={`${forum.forumName} banner`} className="forum-banner-image" />
                        </div>
                        <p>{forum.description}</p>
                    </div>
                    <div className="forum-stats-and-last-thread">
                        <div className="forum-stats">
                            <p>{forum.numThreads} Threads</p>
                            <p>{forum.numMessages} Messages</p>
                        </div>
                        <div className="forum-last-thread">
                            <LastThreadInfo lastThread={forum.lastThread} />
                        </div>
                    </div>
                </div>
            </div>

            {subForums.length > 0 && (
                <div className="subforums">
                    <h3>Subforums</h3>
                    <ul>
                        {subForums.map(subForum => (
                            <li key={subForum.id} className="subforum-item">
                                <div className="subforum-info">
                                    <h4 className="subforum-title">
                                        <Link to={`/forum/${subForum.id}`}>{subForum.name}</Link>
                                    </h4>
                                    <p>{subForum.description}</p>
                                </div>
                                <LastThreadInfo lastThread={subForum.lastThread} />
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            <div className="threads">
                <h3>Threads</h3>
                <ThreadList forumId={forum.forumId} />
            </div>
        </div>
    );
};

export default ForumDetail;
